import requests
import json
import os
import sys
import re

try:
    baseurl = os.environ["LAB_URL"]
    token = os.environ["LAB_TOKEN"]
except Exception:
    print("missing LAB_URL or LAB_TOKEN", file=sys.stderr)
    sys.exit(2)

if not isinstance(baseurl, str) or not isinstance(token, str):
    print("invalid LAB_URL or LAB_TOKEN type", file=sys.stderr)
    sys.exit(2)

if baseurl == "" or token == "":
    print("empty LAB_URL or LAB_TOKEN", file=sys.stderr)
    sys.exit(2)

headers = {"Authorization": "Bearer " + token}
base = baseurl.rstrip("/")

try:
    rusers = requests.get(base + "/api/users", headers=headers, timeout=10)
except Exception as ex:
    print("GET /api/users failed: " + str(ex), file=sys.stderr)
    sys.exit(2)

if rusers.status_code != 200:
    print("GET /api/users status " + str(rusers.status_code), file=sys.stderr)
    sys.exit(2)

try:
    users = rusers.json()
except Exception as ex:
    print("invalid JSON /api/users: " + str(ex), file=sys.stderr)
    sys.exit(2)

try:
    rev = requests.get(base + "/admin/users", headers=headers, timeout=10)
except Exception as ex:
    print("GET /admin/users failed: " + str(ex), file=sys.stderr)
    sys.exit(2)

if rev.status_code != 200:
    print("GET /admin/users status " + str(rev.status_code), file=sys.stderr)
    sys.exit(2)

if not isinstance(users, list):
    print("unexpected /api/users format", file=sys.stderr)
    sys.exit(2)

admins = []
flagged = []

for item in users:
    if not isinstance(item, dict):
        print("unexpected user entry format", file=sys.stderr)
        sys.exit(2)
    if "login" not in item or "email" not in item or "role" not in item:
        print("missing login email or role", file=sys.stderr)
        sys.exit(2)
    loginval = item["login"]
    emailval = item["email"]
    roleval = item["role"]
    if not isinstance(loginval, str) or not isinstance(emailval, str) or not isinstance(roleval, str):
        print("invalid user field type", file=sys.stderr)
        sys.exit(2)
    if roleval == "admin":
        admins.append(item)
        loginlow = loginval.lower().strip()
        emaillow = emailval.lower().strip()
        if "@" not in emaillow:
            print("invalid admin email format", file=sys.stderr)
            sys.exit(2)
        parts = emaillow.split("@")
        localpart = parts[0]
        if localpart == "":
            print("invalid admin email format", file=sys.stderr)
            sys.exit(2)
        loginok = re.match(r"^[a-z][a-z0-9\-]*\.[a-z][a-z0-9\-]*$", loginlow)
        emailshared = False
        if "." not in localpart:
            emailshared = True
        if "partage" in emaillow:
            emailshared = True
        if localpart in ["admin", "root", "ops", "administrator", "superadmin", "service", "support", "system"]:
            emailshared = True
        if loginok is None or emailshared:
            flagged.append({"login": loginval, "email": emailval})

observed = flagged
expected = "0 users with role admin having generic login or shared mailbox"
countadmin = len(admins)
countflag = len(flagged)
if countflag == 0:
    status = "pass"
else:
    status = "fail"
detail = "Checked " + str(countadmin) + " admin accounts and found " + str(countflag) + " with generic login or shared mailbox"
print(json.dumps({"status": status, "observed": observed, "expected": expected, "detail": detail, "evidence_page": "/admin/users"}))
